observation.command:
cd /workspace/src/Bovis.Web && cat > local.json <<'EOF'
{
  "ConnectionStrings": {
    "DataConnection": "sqlite:bohris.db",
    "ConfigConnection": "sqlite:config.db",
    "DataBackend": "LBEG"
  }
}
EOF
export DOTNET_CLI_TELEMETRY_OPTOUT=1 && nohup dotnet run --no-build -- server > /tmp/bovis_lbeg.log 2>&1 &
echo "pid $!"; sleep 40; echo "=== tail ==="; tail -20 /tmp/bovis_lbeg.log; echo "=== port ==="; ss -ltnp 2>/dev/null | grep 18080
